// Words splits text on whitespace.
func Words(s string) []string {
	return strings.Fields(s)
}

// Wrap wraps text into lines of at most width characters, breaking only at spaces.
// A word longer than width goes on a line of its own, whole.
// Runs of whitespace collapse; no line begins or ends with a space.
// Empty or whitespace-only input returns an empty slice.
// A width of zero or less returns nil.
func Wrap(text string, width int) []string {
	if width <= 0 {
		return nil
	}
	words := strings.Fields(text)
	if len(words) == 0 {
		return nil
	}
	lines := []string{words[0]}
	for _, w := range words[1:] {
		last := lines[len(lines)-1]
		if len(last)+1+len(w) <= width {
			lines[len(lines)-1] = last + " " + w
		} else {
			lines = append(lines, w)
		}
	}
	return lines
}

