package text

import "testing"

func TestWords(t *testing.T) {
	if len(Words("a b  c")) != 3 {
		t.Fatal("expected three words")
	}
}

func TestWrap(t *testing.T) {
	tests := []struct {
		text   string
		width  int
		want   []string
	}{
		{
			text:  "",
			width: 10,
			want:  nil,
		},
		{
			text:  "   ",
			width: 10,
			want:  nil,
		},
		{
			text:  "hello world",
			width: 10,
			want: []string{
				"hello",
				"world",
			},
		},
		{
			text:  "the quick brown fox jumps over the lazy dog",
			width: 15,
			want: []string{
				"the quick",
				"brown fox",
				"jumps over",
				"the lazy dog",
			},
		},
		{
			text:  "superlongword short",
			width: 5,
			want: []string{
				"superlongword",
				"short",
			},
		},
		{
			text:  "hello world",
			width: 0,
			want:  nil,
		},
		{
			text:  "hello world",
			width: -1,
			want:  nil,
		},
		{
			text:  "  hello   world  ",
			width: 20,
			want: []string{
				"hello world",
			},
		},
		{
			text:  "a bb ccc dddd eeeee ffffff ggggggg hhhhhhhh iiiiiiiijjjjjjjj",
			width: 10,
			want: []string{
				"a bb ccc",
				"dddd eeeee",
				"ffffff",
				"ggggggg",
				"hhhhhhhh",
				"iiiiiiiii",
				"jjjjjjjj",
			},
		},
	}
	for _, tc := range tests {
		got := Wrap(tc.text, tc.width)
		if len(got) != len(tc.want) || (len(got) == 0 && got != nil) {
			t.Errorf("Wrap(%q, %d) = %v, want %v", tc.text, tc.width, got, tc.want)
			continue
		}
		for i, line := range got {
			if line != tc.want[i] {
				t.Errorf("Wrap(%q, %d)[%d] = %q, want %q", tc.text, tc.width, i, line, tc.want[i])
			}
		}
	}
}

